<?php $statuses = ['pending' => 'Đang giữ ghế', 'paid' => 'Đã thanh toán', 'cancelled' => 'Đã hủy', 'expired' => 'Hết hạn']; ?>
<div class="page-heading"><span class="eyebrow">ĐƠN VÉ <?= e($order['reference']) ?></span><h1><?= e($order['title']) ?></h1><span class="badge badge-<?= e($order['status']) ?>"><?= e($statuses[$order['status']] ?? $order['status']) ?></span><?php if ($order['payment_method'] === 'demo'): ?><span class="badge badge-warning">Vé thử nghiệm · không thu tiền</span><?php endif; ?></div>
<div class="two-columns"><section class="panel"><h2>Thông tin suất chiếu</h2><dl class="details"><dt>Rạp</dt><dd><?= e($order['cinema_name']) ?></dd><dt>Địa chỉ</dt><dd><?= e($order['address']) ?></dd><dt>Phòng</dt><dd><?= e($order['room_name']) ?></dd><dt>Suất chiếu</dt><dd><?= date('H:i · d/m/Y', strtotime($order['starts_at'])) ?></dd><dt>Người đặt</dt><dd><?= e($order['customer_name']) ?></dd><dt>Ngày đặt</dt><dd><?= date('H:i · d/m/Y', strtotime($order['created_at'])) ?></dd><dt>Thanh toán</dt><dd><?= $order['payment_method'] === 'demo' ? 'Thử nghiệm' : 'Tại quầy' ?></dd></dl><?php if ($order['status'] === 'pending'): ?><div class="alert alert-info">Giữ ghế đến <strong><?= date('H:i:s · d/m/Y', strtotime($order['expires_at'])) ?></strong>. Đơn tự hết hạn nếu chưa thanh toán.</div><?php endif; ?></section>
<section class="panel"><h2>Chi tiết vé & combo</h2><div class="table-scroll"><table><thead><tr><th>Hạng mục</th><th>Số lượng</th><th>Thành tiền</th></tr></thead><tbody><?php foreach ($order['items'] as $item): ?><tr><td><?= $item['kind'] === 'seat' ? 'Ghế ' : '' ?><?= e($item['item_name']) ?></td><td><?= (int)$item['quantity'] ?></td><td><?= money((int)$item['quantity'] * (int)$item['unit_price']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="total-row"><span>Tổng cộng</span><strong><?= money($order['total']) ?></strong></div>
<?php if ($order['status'] === 'pending'): ?><form method="post" class="actions"><?= csrf_field() ?><?php if ($adminPage || ($order['payment_method'] === 'demo' && config('allow_demo_payment'))): ?><button class="button" name="action" value="pay" type="submit"><?= $adminPage ? 'Xác nhận đã thu tiền' : 'Xác nhận thanh toán thử nghiệm' ?></button><?php endif; ?><button class="button button-danger" name="action" value="cancel" type="submit" data-confirm="Hủy đơn và trả lại các ghế đang giữ?">Hủy đơn</button></form><?php endif; ?>
<?php if ($order['status'] === 'paid'): ?><p class="muted">Xuất trình mã đơn <strong><?= e($order['reference']) ?></strong> tại quầy để kiểm tra vé.</p><button type="button" class="button button-outline" data-print>In thông tin vé</button><?php endif; ?></section></div>
